<?php require_once 'config.php'; require_login();
if(isset($_GET['approve']) && is_admin()){ $pdo->prepare("UPDATE income SET status='approved',approved_by=?,approved_at=NOW() WHERE id=?")->execute([$_SESSION['user_id'],$_GET['approve']]); header('Location: income.php'); exit; }
if(isset($_GET['reject']) && is_admin()){ $pdo->prepare("UPDATE income SET status='rejected',approved_by=?,approved_at=NOW() WHERE id=?")->execute([$_SESSION['user_id'],$_GET['reject']]); header('Location: income.php'); exit; }
if($_SERVER['REQUEST_METHOD']==='POST'){
 $file=null; if(!empty($_FILES['attachment']['name'])){ $ext=pathinfo($_FILES['attachment']['name'],PATHINFO_EXTENSION); $file='income_'.time().'_'.rand(1000,9999).'.'.$ext; move_uploaded_file($_FILES['attachment']['tmp_name'],'uploads/'.$file); }
 $pdo->prepare('INSERT INTO income(received_by,category_id,customer_name,project_service,invoice_ref,payment_method,amount,currency,income_date,notes,attachment_file) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$_SESSION['user_id'],$_POST['category_id'],$_POST['customer_name'],$_POST['project_service'],$_POST['invoice_ref'],$_POST['payment_method'],$_POST['amount'],$_POST['currency'],$_POST['income_date'],$_POST['notes'],$file]); header('Location: income.php'); exit;
}
$cats=$pdo->query("SELECT * FROM categories WHERE type='income' ORDER BY name")->fetchAll();
$rows=$pdo->query("SELECT i.*,u.name user,c.name cat FROM income i JOIN users u ON u.id=i.received_by LEFT JOIN categories c ON c.id=i.category_id ORDER BY i.id DESC")->fetchAll();
include 'includes/header.php'; ?>
<h1>Income / Revenue</h1><div class="card"><h3>Add Income</h3><form method="post" enctype="multipart/form-data"><div class="grid"><div><label>Category</label><select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select></div><div><label>Customer Name</label><input name="customer_name"></div><div><label>Project / Service</label><input name="project_service"></div><div><label>Invoice Ref</label><input name="invoice_ref"></div><div><label>Payment Method</label><input name="payment_method" placeholder="Cash / Bank / Wallet"></div><div><label>Amount</label><input name="amount" type="number" step="0.01" required></div><div><label>Currency</label><input name="currency" value="EGP"></div><div><label>Date</label><input name="income_date" type="date" value="<?=date('Y-m-d')?>" required></div></div><label>Notes</label><textarea name="notes"></textarea><label>Invoice / Attachment</label><input type="file" name="attachment"><button>Submit Income</button></form></div>
<div class="card"><h3>Income List</h3><table><tr><th>Date</th><th>Received By</th><th>Customer</th><th>Project</th><th>Amount</th><th>Status</th><th>Attachment</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['income_date'])?></td><td><?=h($r['user'])?></td><td><?=h($r['customer_name'])?></td><td><?=h($r['project_service'])?></td><td><?=number_format($r['amount'],2).' '.h($r['currency'])?></td><td><span class="status <?=$r['status']?>"><?=h($r['status'])?></span></td><td><?php if($r['attachment_file']):?><a class="btn secondary" href="uploads/<?=h($r['attachment_file'])?>" target="_blank">Open</a><?php endif;?></td><td class="actions"><?php if(is_admin() && $r['status']=='pending'):?><a class="btn ok" href="?approve=<?=$r['id']?>">Approve</a><a class="btn danger" href="?reject=<?=$r['id']?>">Reject</a><?php endif;?></td></tr><?php endforeach;?></table></div>
<?php include 'includes/footer.php'; ?>
